use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde::Deserialize;
use std::env;

mod ldap_client {
    use std::fmt;

    #[derive(Clone)]
    pub struct LdapFilter {
        components: Vec<FilterComponent>,
    }

    #[derive(Clone)]
    enum FilterComponent {
        Equality(String, String),
        And(Vec<FilterComponent>),
    }

    impl LdapFilter {
        pub fn new() -> Self {
            LdapFilter { components: Vec::new() }
        }

        pub fn add_equality(&mut self, attr: &str, value: &str) {
            self.components.push(FilterComponent::Equality(
                sanitize_attribute(attr),
                encode_filter_value(value),
            ));
        }

        pub fn add_raw_component(&mut self, component: FilterComponent) {
            self.components.push(component);
        }

        pub fn to_filter_string(&self) -> String {
            if self.components.len() == 1 {
                format_component(&self.components[0])
            } else {
                let parts: Vec<String> = self.components.iter()
                    .map(|c| format_component(c))
                    .collect();
                format!("(&{})", parts.join(""))
            }
        }
    }

    fn format_component(comp: &FilterComponent) -> String {
        match comp {
            FilterComponent::Equality(attr, val) => format!("({}={})", attr, val),
            FilterComponent::And(comps) => {
                let parts: Vec<String> = comps.iter().map(|c| format_component(c)).collect();
                format!("(&{})", parts.join(""))
            }
        }
    }

    pub fn sanitize_attribute(attr: &str) -> String {
        attr.chars()
            .filter(|c| c.is_alphanumeric() || *c == '-' || *c == '.')
            .collect()
    }

    pub fn encode_filter_value(value: &str) -> String {
        let mut result = String::with_capacity(value.len());
        for ch in value.chars() {
            match ch {
                '\\' => result.push_str("\\5c"),
                '*' => result.push_str("\\2a"),
                '(' => result.push_str("\\28"),
                ')' => result.push_str("\\29"),
                '\0' => result.push_str("\\00"),
                _ => result.push(ch),
            }
        }
        result
    }

    pub struct LdapConnection {
        pub base_dn: String,
    }

    impl LdapConnection {
        pub fn search(&self, filter: &str) -> Result<Vec<String>, String> {
            // In production, this calls ldap3 crate
            println!("Executing LDAP search: base={}, filter={}", self.base_dn, filter);
            Ok(vec![format!("result for filter: {}", filter)])
        }
    }
}

mod auth_service {
    use super::ldap_client::{LdapFilter, LdapConnection, encode_filter_value};

    pub struct AuthConfig {
        pub user_object_class: String,
        pub group_base_dn: String,
        pub service_account_filter: Option<String>,
    }

    pub fn build_user_search_filter(
        username: &str,
        config: &AuthConfig,
        conn: &LdapConnection,
    ) -> String {
        let mut filter = LdapFilter::new();
        filter.add_equality("objectClass", &config.user_object_class);
        filter.add_equality("uid", username);

        if let Some(ref svc_filter) = config.service_account_filter {
            let expanded = expand_template(svc_filter, username);
            let base_filter = filter.to_filter_string();
            return format!("(&{}{})", base_filter, expanded);
        }

        filter.to_filter_string()
    }

    fn expand_template(template: &str, username: &str) -> String {
        // Template expansion for service account filters
        // Encodes the username before substitution to prevent injection
        let safe_username = encode_filter_value(username);
        template.replace("{uid}", &safe_username)
    }

    pub fn authenticate_user(
        username: &str,
        _password: &str,
        config: &AuthConfig,
        conn: &LdapConnection,
    ) -> Result<bool, String> {
        let filter = build_user_search_filter(username, config, conn);
        let results = conn.search(&filter)?;
        Ok(!results.is_empty())
    }
}

#[derive(Deserialize)]
struct LoginRequest {
    username: String,
    password: String,
}

async fn login_handler(
    body: web::Json<LoginRequest>,
    config: web::Data<auth_service::AuthConfig>,
    conn: web::Data<ldap_client::LdapConnection>,
) -> HttpResponse {
    if body.username.is_empty() || body.password.is_empty() {
        return HttpResponse::BadRequest().json("Missing credentials");
    }

    if body.username.len() > 128 {
        return HttpResponse::BadRequest().json("Username too long");
    }

    match auth_service::authenticate_user(
        &body.username,
        &body.password,
        config.get_ref(),
        conn.get_ref(),
    ) {
        Ok(true) => HttpResponse::Ok().json("Authenticated"),
        Ok(false) => HttpResponse::Unauthorized().json("Invalid credentials"),
        Err(e) => {
            eprintln!("Auth error: {}", e);
            HttpResponse::InternalServerError().json("Internal error")
        }
    }
}

async fn health_handler() -> HttpResponse {
    HttpResponse::Ok().json("healthy")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let ldap_url = env::var("LDAP_URL").unwrap_or_else(|_| "ldap://ldap-svc:389".to_string());
    let base_dn = env::var("LDAP_BASE_DN").unwrap_or_else(|_| "dc=company,dc=com".to_string());
    let svc_filter = env::var("LDAP_SVC_ACCOUNT_FILTER").ok();

    let config = auth_service::AuthConfig {
        user_object_class: "inetOrgPerson".to_string(),
        group_base_dn: env::var("LDAP_GROUP_BASE").unwrap_or_else(|_| "ou=groups,dc=company,dc=com".to_string()),
        service_account_filter: svc_filter,
    };

    let conn = ldap_client::LdapConnection { base_dn };

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(config.clone()))
            .app_data(web::Data::new(conn.clone()))
            .route("/login", web::post().to(login_handler))
            .route("/health", web::get().to(health_handler))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}

impl Clone for auth_service::AuthConfig {
    fn clone(&self) -> Self {
        auth_service::AuthConfig {
            user_object_class: self.user_object_class.clone(),
            group_base_dn: self.group_base_dn.clone(),
            service_account_filter: self.service_account_filter.clone(),
        }
    }
}

impl Clone for ldap_client::LdapConnection {
    fn clone(&self) -> Self {
        ldap_client::LdapConnection {
            base_dn: self.base_dn.clone(),
        }
    }
}
